command:
if [ -f /etc/nginx/http.d/default.conf ] && [ ! -f /etc/nginx/http.d/default.conf.package ]; then
    cp -p /etc/nginx/http.d/default.conf /etc/nginx/http.d/default.conf.package
fi
cat > /etc/nginx/http.d/default.conf <<'ANTRIEB_NGINX_CONF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node1;

    ssl_certificate     /etc/nginx/tls/current/server.crt;
    ssl_certificate_key /etc/nginx/tls/current/server.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:TLS:1m;
    ssl_session_timeout 10m;

    location / {
        default_type text/plain;
        return 200 "certificate rotation service is healthy\n";
    }
}
ANTRIEB_NGINX_CONF
cat > /etc/periodic/daily/nginx-cert-renew <<'ANTRIEB_CRON'
#!/bin/sh
exec /usr/local/sbin/rotate-nginx-cert
ANTRIEB_CRON
chmod 750 /etc/periodic/daily/nginx-cert-renew
nginx -t
rc-update add nginx default
rc-update add crond default
rc-service nginx start
rc-service crond start
rc-service nginx status
rc-service crond status
ss -ltnp | grep ':8443'

